package dev.gamersclt.batcaverna.nativeapp;
import android.content.Context;
import android.widget.*;
import org.json.*;
import java.util.*;
final class TitleSelectionDialog {
 static void show(Context c,JSONObject profile,Runnable saved){NativeSheet sheet=new NativeSheet(c,"Título do perfil");TextView state=NativeSheet.text(c,"Consultando seus títulos desbloqueados…",13,0xffb7a6ff);sheet.body.addView(state);sheet.show();new AccountRepository(c).ranking((rows,error)->{if(!sheet.dialog.isShowing())return;if(error!=null){state.setText(error);return;}String user=c.getSharedPreferences("batcaverna",0).getString("user_id","");JSONObject me=null;for(int i=0;i<rows.length();i++)if(user.equals(rows.optJSONObject(i).optString("id")))me=rows.optJSONObject(i);if(me==null){state.setText("Progresso indisponível.");return;}int level=ProfileProgress.level(me.optLong("xp"));List<Integer> values=new ArrayList<>();List<String> labels=new ArrayList<>();values.add(0);labels.add("Acompanhar meu nível atual");for(int threshold:new int[]{1,2,4,7,10,15,20,30})if(threshold<=level){values.add(threshold);labels.add(ProfileProgress.title(threshold)+" • Nível "+threshold);}Spinner choice=NativeSheet.options(c,labels.toArray(new String[0]));int old=profile.optInt("titulo_destaque_nivel");choice.setSelection(Math.max(0,values.indexOf(old)));sheet.body.addView(choice);state.setText("Somente títulos já desbloqueados.");Button save=new Button(c);save.setText("Salvar título");AppStyle.button(save,true);sheet.body.addView(save);save.setOnClickListener(v->{save.setEnabled(false);sheet.busy(true);JSONArray games=profile.optJSONArray("jogos_destaque"),ach=profile.optJSONArray("conquistas_destaque");new AccountRepository(c).saveHighlights(games==null?new JSONArray():games,ach==null?new JSONArray():ach,values.get(choice.getSelectedItemPosition()),(r,e)->{sheet.busy(false);if(e!=null){state.setText(e);return;}sheet.dialog.dismiss();saved.run();});});});}
}
